SELECT table_schema, table_name, row_count FROM LIBRARY_MARTS.information_schema.tables WHERE table_name ILIKE '%INJURY_VIOLENCE_COUNTY%' OR table_name ILIKE '%DEA_ARCOS%';;
SELECT YEAR(TRANSACTION_DATE) y, COUNT(*) n, SUM(DOSAGE_UNITS) du, TYPEOF(ANY_VALUE(DOSAGE_STRENGTH::variant)) t FROM LIBRARY_MARTS.HEALTH.HEALTH__FED_DEA_ARCOS WHERE TRANSACTION_CODE='S' GROUP BY 1 ORDER BY 1;;
SELECT column_name, data_type FROM LIBRARY_MARTS.information_schema.columns WHERE table_name='HEALTH__FED_CDC_INJURY_VIOLENCE_COUNTY' OR (table_name='HEALTH__FED_DEA_ARCOS' AND column_name IN ('DOSAGE_STRENGTH','DOSAGE_UNITS','BUYER_COUNTY_FIPS'))
